using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
//    Use an empty resolver so nothing is resolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => { if (ti.Type == typeof(Secret)) ti.CreateObject = null; } }
    }
};

// Person IS resolvable via the default resolver
if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {info!.Type.Name}");
else
    Console.WriteLine("\nTryGetTypeInfo(Person) returned false");

// Now use a resolver that resolves nothing (returns null for every type)
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers → always null
};

if (empty.TryGetTypeInfo(typeof(Secret), out JsonTypeInfo? secretInfo))
    Console.WriteLine($"TryGetTypeInfo(Secret) succeeded: {secretInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo(Secret) returned false — no exception thrown!");

// Types used in the demo
record Person(string Name, int Age);
record Secret(string Value);

